-- Replaces the human-security dimensions of the recommendations of A/HRC/60/8 with HRCT's reviewed
-- classification. The first assignment gave almost three dimensions to each recommendation
-- (954 links: community security in 222 of the 324 recommendations, political security in 202,
-- food security in 22 although no recommendation names food). Each recommendation was classified
-- again from its official text: a dimension is assigned only when the measure requested responds
-- to a threat that belongs to it, and each link says why.
-- Criteria: docs/human-security.md. Review: data/human-security/hrct-review-spain-upr4.json.
-- The rows below are the output of `node scripts/human-security-review.mjs --sql`.
-- Safe to run again.

alter table public.commitment_human_security
  add column if not exists reviewed_at date;

create or replace view public.hrct_public_human_security with (security_invoker = true) as
select c.public_id, d.code, d.name, d.description, chs.is_primary, chs.rationale, chs.reviewed_at
from public.commitment_human_security chs
join public.commitments c on c.id=chs.commitment_id
join public.human_security_dimensions d on d.id=chs.dimension_id
where c.publication_status='published';

create temp table human_security_review (n int, code text, is_primary boolean not null, rationale text not null, primary key (n, code));

-- (recommendation 50.n, dimension, primary, why)

-- Links of the catalogue that the review does not keep.
delete from public.commitment_human_security h
using public.commitments c, public.human_security_dimensions d
where c.id = h.commitment_id
  and d.id = h.dimension_id
  and c.public_id like 'ESP-UPR4-050.%'
  and not exists (select 1 from human_security_review r where c.public_id = 'ESP-UPR4-050.' || r.n and r.code = d.code);

select c.id, d.id, r.is_primary, r.rationale, date '2026-10-06'
from human_security_review r
  join public.commitments c on c.public_id = 'ESP-UPR4-050.' || r.n
  join public.human_security_dimensions d on d.code = r.code
on conflict (commitment_id, dimension_id) do update set is_primary = excluded.is_primary, rationale = excluded.rationale, reviewed_at = excluded.reviewed_at;

drop table human_security_review;
